# Generated by manage.py generate_test_cases.
from unittest.mock import patch

from django.contrib.auth import get_user_model
from django.http import HttpResponse

from bloomerp.models.communication.instant_messaging import IMConversation
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestCreateGroupComponent(BloomerpComponentTestCase):
    """Exercise internal group setup through the generated component boundary."""

    view_name = "components_im_create_group"

    def prepare_members(self, scenario: RequestScenario) -> None:
        """Choose two distinct staff and include duplicate/self inputs to check normalization."""
        colleague = get_user_model().objects.create(
            username="group_colleague", is_staff=True
        )
        scenario.data = {
            "name": "Project team",
            "recipients": [
                str(self.normal_user.pk),
                str(colleague.pk),
                str(colleague.pk),
            ],
        }

    def prepare_inactive(self, scenario: RequestScenario) -> None:
        """Attempt to add an inactive staff account through the picker."""
        self.prepare_members(scenario)
        self.normal_user.is_active = False
        self.normal_user.save(update_fields=["is_active"])

    def validate_created(self, response: HttpResponse) -> bool:
        """Verify one owner, two members, a native group and the reusable conversation UI."""
        chat = IMConversation.objects.get(name="Project team")
        return (
            chat.kind == "group"
            and chat.connection_id is None
            and chat.participants.count() == 3
            and chat.participants.get(user=self.admin_user).role == "owner"
            and "im:conversation-opened" in response["HX-Trigger"]
        )

    def validate_small_group(self, response: HttpResponse) -> bool:
        """Verify a group can contain the owner and just one other staff user."""
        chat = IMConversation.objects.get(name="Small")
        return chat.kind == "group" and chat.participants.count() == 2

    def validate_no_group(self, response: HttpResponse) -> bool:
        """Ensure rejected configuration leaves no partial group."""
        return not IMConversation.objects.exists()

    def prepare_email_directory(self, scenario: RequestScenario) -> None:
        """Use email login with recipient ordering opposite to username ordering."""
        self.enterContext(patch.object(get_user_model(), "USERNAME_FIELD", "email"))
        self.normal_user.email = "z-recipient@example.test"
        self.normal_user.save(update_fields=["email"])
        self.first_recipient = get_user_model().objects.create(
            username="zzz_colleague", email="a-recipient@example.test", is_staff=True
        )

    def validate_email_ordering(self, response: HttpResponse) -> bool:
        """Ensure the picker orders recipients by their configured login field."""
        recipients = response.context["form"].fields["recipients"].queryset
        return list(recipients.values_list("pk", flat=True)) == [
            self.first_recipient.pk,
            self.normal_user.pk,
        ]

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover picker rendering, creation and invalid staff selections."""
        return [
            RequestScenario(
                name="Render standard picker",
                user=self.admin_user,
                expected=ExpectedResult(
                    response_validators=[self.contains_text('bloomerp-component="foreign-field-widget"'),
                        self.does_not_contain_text('New internal group'),
                        self.contains_text('is_staff')]
                ),
            ),
            RequestScenario(
                name="Create internal group",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_members,
                expected=ExpectedResult(
                    response_validators=[
                        self.validate_created,
                        self.contains_text("bloomerp-text-editor"),
                    ]
                ),
            ),
            RequestScenario(
                name="Reject inactive recipient",
                method="POST",
                user=self.admin_user,
                prepare=self.prepare_inactive,
                expected=ExpectedResult(response_validators=[self.validate_no_group]),
            ),
            RequestScenario(
                name="Create group with one other participant",
                method="POST",
                user=self.admin_user,
                data={"name": "Small", "recipients": [str(self.normal_user.pk)]},
                expected=ExpectedResult(
                    response_validators=[
                        self.validate_small_group,
                    ]
                ),
            ),
            RequestScenario(
                name="Require authentication", expected=ExpectedResult(status_code=302)
            ),
            RequestScenario(
                name="Group picker orders by the configured email login field",
                user=self.admin_user,
                prepare=self.prepare_email_directory,
                expected=ExpectedResult(
                    response_validators=[self.validate_email_ordering]
                ),
            ),
        ]
